"""Use actual packet whitelist only; derive a fresh periodic confidence set and topology."""
import sys,time,gzip,signal,types
from afternoon_tools import *
import numpy as np

def main():
 out=O/'post_observation';out.mkdir();start=time.monotonic();signal.signal(signal.SIGALRM,lambda *_:(_ for _ in()).throw(TimeoutError('POST_OBSERVATION600')));signal.alarm(min(600,max(1,int(remaining()-30))));task=json.loads((C/'OBSERVER_TASK.json').read_text());physical=Path(task['output']);assert json.loads((physical/'FINAL_INDEPENDENT_AUDIT.json').read_text())['passed'];setup=json.loads((physical/'physics/SETUP.json').read_text());packets=json.loads(gzip.open(physical/'physics/SENSORS.json.gz','rt').read());causal=load('afternoon_causal_packet_estimator',R/'experiments/v1024_full_route_execution/causal.py');norm=load('afternoon_declared_norm_estimator',R/'experiments/v1037_periodic_norm_source/periodic_norm.py');e=causal.Evidence(setup['known']);e.periodic=norm.PeriodicSupport();last=-1
 for scan in packets:
  assert scan['native_tick']>=last,'NONCAUSAL_SENSOR_ORDER';last=scan['native_tick'];e.update({k:scan[k]for k in ['native_tick','time','xy','yaw','ranges']})
 p=json.loads((physical/'ACTUAL_FINAL_PACKET.json').read_text());assert last==p['native_tick']and abs(e.last_scan['time']-p['sim_time'])<1e-8,'FINAL_SOURCE_NOT_FRESH';v=types.SimpleNamespace(d=types.SimpleNamespace(time=p['sim_time']));source=e.source(v);assert source['source_age_s']<=.051 and source['source_native_tick']==p['native_tick'];dump(out/'FRESH_SOURCE.json',source);dump(out/'OBSERVATION_EVIDENCE.json',{'packet_count':len(packets),'new_packets':sum(r['native_tick']>20160 for r in packets),'last_native':last,'first_tracked_packet':e.first,'only_keys':['native_tick','time','xy','yaw','ranges'],'truth_phase_axis_or_raw_actor_labels_used':False,'constraints':e.periodic.constraints})
 sys.path.insert(0,str(R/'experiments/v1135_causal_batch'));from joint_domain import Domain,NORMALS
 from geometry import Geometry
 domain=Domain(source['periodic']['vertices']);centers=(np.arange(256)+.5)*(2*np.pi/.32/256);upper,dual,residual=domain.table(centers);reconstructed=np.array([[[nx,nx*np.sin(.32*t),nx*np.cos(.32*t),ny,ny*np.sin(.32*t),ny*np.cos(.32*t)]for nx,ny in NORMALS]for t in centers])-np.einsum('tnj,jk->tnk',dual,domain.A);certificate=np.einsum('tnj,j->tn',dual,domain.b)+np.where(reconstructed>=0,reconstructed*domain.upper,reconstructed*domain.lower).sum(axis=2)+1e-8;assert np.all(dual>=0)and abs(certificate-upper).max()<=1e-9,'DUAL_RECONSTRUCTION_FAILED';bounds=upper+.08*((2*np.pi/.32/256)/2+.075)+2e-7;np.savez_compressed(out/'JOINT_TABLE.npz',bounds=bounds,centers=centers,dual=dual,residual=residual,A=domain.A,b=domain.b,lower=domain.lower,upper_box=domain.upper);x={'setup':setup,'packet':p,'source':source,'goal':[4.,-2.],'safe_terminal_pose':[4.,-1.85,0.]};dump(out/'FRESH_INPUT.json',x);g=Geometry(x,{'bounds':bounds,'centers':centers});sys.path.insert(0,str(R/'experiments/v1138_backup_corridor'));import corridor_tools as t;lib=t.library();graph,path=t.graph(lib,setup['known']['known_rectangles'],setup['known']['known_circles'],g.cycle_bounds,np.array(p['body'][:3]),[4.,-1.85],True,seconds=90.)
 if graph['found']:
  proof=t.certify(g,path,True);assert proof['passed'],'FRESH_GEOMETRY_CERTIFICATE_FAILED';graph['independent_geometry']=proof;dump(out/'CYCLE_PATH.json',{'path':path,'analysis':graph})
 old_input=json.loads((R/'runs/v858_nav2_verified/v1122/r00_m15_b8_main_WEST_EAST/COUPLED_ENTRY.json').read_text());old_table=np.load(R/'runs/v1135_causal_batch/domain/JOINT_TABLE.npz');old_geometry=Geometry(old_input,{k:old_table[k]for k in ['bounds','centers']});width_before=old_geometry.cycle_bounds[:8]+old_geometry.cycle_bounds[8:];width_after=g.cycle_bounds[:8]+g.cycle_bounds[8:];result={'cycle_widths_before_m':width_before,'cycle_widths_after_m':width_after,'closed':True,'passed':True,'fresh_source_from_actual_measurements':True,'fresh_source_native':last,'source_age_s':source['source_age_s'],'rigid_cycle_corridor_found':graph['found'],'graph':graph,'lp_calls':domain.calls,'models':0,'physical_integrations':0,'analytical_dynamics_integrations':0,'actual_navigation_or24_started':False,'wall_s':time.monotonic()-start,'truth_inputs_used':False,'finite_graph_not_global_proof':True};signal.alarm(0);dump(out/'RESULT.json',result);print(encode(result))
if __name__=='__main__':main()
